import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

function stripLocation(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stripLocation);
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = k.toLowerCase().includes('location') ? null : v;
    }
    return out;
  }
  return value;
}

test.describe('זמני היום', () => {
  test('ZM-04 Нет местоположения → явное состояние, без примерного времени #6a86f7df @prod-safe @mobile', async ({ page }) => {
    // 1. До перехода: перехватить ответ user_profiles и обнулить поля местоположения (данные профиля не меняются).
    await page.route('**/rest/v1/user_profiles*', async (route) => {
      const response = await route.fetch();
      let json: unknown;
      try {
        json = await response.json();
      } catch {
        await route.fulfill({ response });
        return;
      }
      await route.fulfill({ response, json: stripLocation(json) });
    });

    // 2. Открыть `/zmanim`.
    await page.goto('/zmanim');
    await expect(page.getByText('לא נשמר מיקום, ולכן אין לפי מה לחשב את זמני היום.')).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('בחירת מיקום בפרופיל')).toBeVisible();

    // Часов нет, строки «הזמנים חושבו עבור…» нет
    await expect(page.getByText(/\b\d{1,2}:\d{2}\b/)).toHaveCount(0);
    await expect(page.getByText('הזמנים חושבו עבור')).toHaveCount(0);

    // Блок «לימוד יומי» показывается
    await expect(page.locator('#zmanim-learning')).toBeVisible({ timeout: 20_000 });
    await expect(page.getByText('דף יומי בבלי')).toBeVisible();
  });
});
